package codicefiscale

import (
	"bufio"
	"bytes"
	"compress/gzip"
	_ "embed"
	"fmt"
	"strconv"
	"strings"
	"sync"
	"time"
)

// data.txt.gz is generated by tools/go-migration/codicefiscale_data.py from
// python-codicefiscale 0.10.3 (codicefiscale.codicefiscale._DATA).
//
//go:embed data.txt.gz
var dataGz []byte

const isoLayout = "2006-01-02T15:04:05"

// place is one birthplace record: the Belfiore code and its validity range.
// A zero created/deleted time means None in the reference data.
type place struct {
	code    string
	created time.Time
	deleted time.Time
}

type lookupData struct {
	municipalities map[string][]*place
	countries      map[string][]*place
	codes          map[string][]*place
}

var (
	dataOnce   sync.Once
	dataLoaded *lookupData
	dataErr    error
)

func loadData() (*lookupData, error) {
	dataOnce.Do(func() {
		dataLoaded, dataErr = parseData(dataGz)
	})
	return dataLoaded, dataErr
}

func parseData(gz []byte) (*lookupData, error) {
	zr, err := gzip.NewReader(bytes.NewReader(gz))
	if err != nil {
		return nil, fmt.Errorf("codicefiscale: open data: %w", err)
	}
	defer zr.Close()
	sc := bufio.NewScanner(zr)
	line := 0
	next := func() (string, error) {
		if !sc.Scan() {
			if err := sc.Err(); err != nil {
				return "", err
			}
			return "", fmt.Errorf("unexpected end of data after line %d", line)
		}
		line++
		return sc.Text(), nil
	}
	fail := func(err error) (*lookupData, error) {
		return nil, fmt.Errorf("codicefiscale: data line %d: %w", line, err)
	}

	header, err := next()
	if err != nil {
		return fail(err)
	}
	if header != "codicefiscale-data v1" {
		return fail(fmt.Errorf("unknown header %q", header))
	}
	n, err := countLine(next, "records")
	if err != nil {
		return fail(err)
	}
	places := make([]place, n)
	for i := range places {
		text, err := next()
		if err != nil {
			return fail(err)
		}
		fields := strings.Split(text, "\t")
		if len(fields) != 3 {
			return fail(fmt.Errorf("record %q", text))
		}
		places[i].code = fields[0]
		if places[i].created, err = parseISO(fields[1]); err != nil {
			return fail(err)
		}
		if places[i].deleted, err = parseISO(fields[2]); err != nil {
			return fail(err)
		}
	}

	d := &lookupData{}
	for _, idx := range []struct {
		name string
		dst  *map[string][]*place
	}{
		{"municipalities", &d.municipalities},
		{"countries", &d.countries},
		{"codes", &d.codes},
	} {
		n, err := countLine(next, "index "+idx.name)
		if err != nil {
			return fail(err)
		}
		m := make(map[string][]*place, n)
		for range n {
			text, err := next()
			if err != nil {
				return fail(err)
			}
			key, ids, ok := strings.Cut(text, "\t")
			if !ok {
				return fail(fmt.Errorf("index entry %q", text))
			}
			var opts []*place
			for id := range strings.SplitSeq(ids, ",") {
				i, err := strconv.Atoi(id)
				if err != nil || i < 0 || i >= len(places) {
					return fail(fmt.Errorf("record index %q", id))
				}
				opts = append(opts, &places[i])
			}
			m[key] = opts
		}
		*idx.dst = m
	}
	if sc.Scan() {
		return fail(fmt.Errorf("trailing data"))
	}
	return d, sc.Err()
}

func countLine(next func() (string, error), prefix string) (int, error) {
	text, err := next()
	if err != nil {
		return 0, err
	}
	rest, ok := strings.CutPrefix(text, prefix+" ")
	if !ok {
		return 0, fmt.Errorf("expected %q, got %q", prefix, text)
	}
	return strconv.Atoi(rest)
}

func parseISO(s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, nil
	}
	return time.Parse(isoLayout, s)
}
